      border-radius: 50%;
      transform: rotate(-14deg);
    }

    @keyframes pulse {
      50% { transform: translateY(-12px) scale(1.03); }
    }

    .stats {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 12px;
    }

    .stat {
      padding: 16px;
      border: 1px solid var(--line);
      border-radius: 22px;
      background: rgba(255, 255, 255, 0.07);
    }

    .stat strong {
